"""Compare serialized v2 exports with v1 and write a measured review report."""
import argparse
import itertools
import json
from collections import Counter
from pathlib import Path

from code.e0.dataset import atomic_write_json, atomic_write_text, sha256_file
from .build import PARTITIONS, read_jsonl, text_fingerprint
from .revise import DEFAULT_OUTPUT, HOLDS, PROJECT, render


def table(headers, rows):
    return "\n".join(["| " + " | ".join(headers) + " |", "| " + " | ".join("---" for _ in headers) + " |", *["| " + " | ".join(map(str, row)) + " |" for row in rows]])


def report(out):
    if (out / "modifier_repair_audit.json").is_file():
        raise RuntimeError("This historical v2 report contains archived environment prose. For repaired outputs use modifier_repair_audit --phase report and runs/hdepic_sft_smoke_8b/README.md.")
    policy = json.loads((out / "correction_policy.json").read_text())
    source = Path(policy["source_v1"])
    changes = list(read_jsonl(out / "changes.jsonl"))
    changes_by_id = {c["id"]: c for c in changes}
    assert len(changes) == len(changes_by_id)
    counts = json.loads((out / "counts.json").read_text())
    manifest = json.loads((out / "split_manifest.json").read_text())
    assert sha256_file(out / "split_manifest.json") == sha256_file(source / "split_manifest.json")
    tally = Counter(); modified_questions = []; compared = 0
    for part in PARTITIONS:
        old = {r["id"]: r for r in read_jsonl(source / "text" / f"{part}.jsonl")}
        present = set()
        paths = [out / "text" / f"{part}.jsonl", out / "swift" / f"{part}.jsonl", out / "swift" / f"{part}.scoring.jsonl", out / "swift" / f"{part}.prompts.jsonl"]
        for index, group in enumerate(itertools.zip_longest(*(read_jsonl(p) for p in paths))):
            r, item, score, prompt = group
            assert all(x is not None for x in group), "Unaligned serialized sidecar length"
            original = old[r["id"]]; present.add(r["id"])
            assert r["target"] == original["target"]
            for key in ("partition", "participant", "video_id", "task", "query_time_sec", "frames"):
                assert r[key] == original[key]
            assert r["input"]["history"] == original["input"]["history"]
            for key in ("current_action", "history_actions", "future_actions", "goal_status", "goal_annotation"):
                assert r["scoring_metadata"][key] == original["scoring_metadata"][key]
            assert score["id"] == r["id"] and score["row_index"] == index
            assert item == render(r, score["frames"])
            assert score == {"row_index": index, "id": r["id"], "partition": part, "participant": r["participant"], "video_id": r["video_id"], "task": r["task"], "query_time_sec": r["query_time_sec"], "frames": score["frames"], **r["scoring_metadata"]}
            assert prompt == {"messages": item["messages"][:2], "images": item["images"]}
            assert [f["path"] for f in score["frames"]] == [f["path"] for f in r["frames"]]
            assert changes_by_id[r["id"]]["status"] == "changed"
            tally[(part, r["task"])] += 1; compared += 1
            if r["task"] == "explain":
                annotation = r["scoring_metadata"]["reason_annotation"]
                for key in ("original_narration", "char_start", "char_end", "extraction_rule", "narration_id", "target"):
                    assert annotation[key] == original["scoring_metadata"]["reason_annotation"][key]
                if r["scoring_metadata"]["question_provenance"]["observed_modifiers"]:
                    modified_questions.append(r["id"])
        excluded = set(old) - present
        assert excluded == {c["id"] for c in changes if c["partition"] == part and c["status"] == "excluded"}
        assert all(old[i]["scoring_metadata"]["current_action"]["narration_id"] in HOLDS for i in excluded)
    sample = list(read_jsonl(out / "sample/training20.scoring.jsonl"))
    sample_categories = Counter((r["task"], r["goal_status"] == "available") for r in sample)
    assert len(sample) == 20 and set(r["partition"] for r in sample) == {"initial_sft"}
    assert set(sample_categories.values()) == {5} and len(sample_categories) == 4
    audit = {"passed": True, "compared_v2_records": compared, "v1_change_or_exclusion_ids": len(changes), "quarantined_ids": [c["id"] for c in changes if c["status"] == "excluded"], "observed_modifier_questions": len(modified_questions), "fixed_split_byte_identical": True, "remaining_targets_byte_equivalent": True, "canonical_classes_source_ids_timestamps_histories_futures_unchanged": True, "individual_frame_paths_unchanged": True, "serialized_swift_sidecars_and_prompts_aligned": True, "sample_training_only_5_per_task_goal_category": True, "dataset_fingerprint": text_fingerprint(out), "semantic_reason_review": "pending_human_review"}
    atomic_write_json(out / "revision_audit.json", audit)
    dims = counts["dimensions"]
    def total(part=None, person=None, task=None, kind="accepted", category=None):
        return sum(x["count"] for x in dims if (part is None or x["partition"] == part) and (person is None or x["participant"] == person) and (task is None or x["task"] == task) and x["kind"] == kind and (category is None or x["category"] == category))
    frames = json.loads((out / "timestamp_leakage_audit.json").read_text())
    env = json.loads((out / "local_environment.json").read_text())
    preflight_path = out / "processor_preflight.json"
    preflight = json.loads(preflight_path.read_text()) if preflight_path.exists() else None
    gpu = env["gpu"].get("devices", env["gpu"].get("last_successful_host_inspection", {}).get("devices", []))
    second = json.loads((out / "second_stage_explain_ids.json").read_text())
    lines = ["# HD-EPIC SFT v2 correction review", "", "**Pending human reason-label review. Dataset preparation only; no model inference, SFT smoke test, training, base predictions, or GRPO was run.**", "", "v1 outputs and cached individual JPEGs are preserved. The fixed split manifest is byte-identical. This pass changes requested-field wording, retains selected observed action-choice details, and quarantines six uncertain Explain labels without inventing replacements. No rejected reasons were recovered and no split was redesigned.", "", "## Corrected partitions", "", table(["Partition", "Participants", "Videos", "Source hours", "Explain", "Track", "Total"], [[p, ", ".join(manifest["partitions"][p]["participants"]), manifest["partitions"][p]["video_count"], f"{manifest['partitions'][p]['duration_hours']:.6f}", total(p, task="explain"), total(p, task="track"), total(p)] for p in PARTITIONS]), "", f"{compared:,} exported records: {total(task='explain'):,} Explain and {total(task='track'):,} Track. {len(changes):,} original v1 IDs are individually accounted for in changes.csv / changes.jsonl. Every retained prompt changed; {len(modified_questions):,} Explain questions additionally preserve observed modifiers. Every retained target, canonical class/source ID, history, future action, timestamp and frame path matches v1.", "", "Explain still queries the target annotated end; Track still queries every five seconds with exactly one ongoing action. Each record supplies 16 individual timestamped frames from the causal five-second lookback and up to eight completed action descriptions. History excludes the target and purpose/method/activity clauses. Track has no current-action ground-truth name in the input. Exactly three future actions start strictly after the query within the video. This remains the fixed first training protocol, not evaluation at every possible moment.", "", "## Prompt and label corrections", "", "Each prompt explicitly requests <why> or <action>, then <goal> only on goal-supervised records, then <next>. Missing/ambiguous goal status remains scoring metadata; it is never an unknown-goal target or a model-uncertainty label. Explain asks for the likely immediate reason from supplied observations. The shared system prompt is in system_prompt.txt.", "", "Explain has a separate action_question_text. Canonical action text and IDs remain in scoring metadata. The training-derived allowlist preserves observed quantity, hip/hand/finger/tool choice, repeat choice, selected destinations, careful manner and opposite-hand glove details. Modifiers retain exact pre-reason narration offsets; broad narration prefixes or implicit purposes are never copied. This conservative pass does not establish complete coverage of every possible choice or manner explanation. correction_policy.json freezes the rules; no test-specific overrides or test predictions were used.", "", "## Quarantine", "", table(["Narration ID", "Partition", "Reason"], [[c["narration_id"], c["partition"], c["reason"]] for c in changes if c["status"] == "excluded"]), "", "quarantined.jsonl retains both the full original v1 record and the held record, including raw narration, original exact span/offsets, revised_span=null, and the hold reason. The three suggested trims remain unconfirmed; no revised ground truth is asserted. The tray cache shows an apparent turn before the placement interval, so temporal attachment is unresolved. Visual/text checking here is assistant review, not an independent human annotation audit.", "", "reason_review.csv contains 50 accepted examples across participants/rules plus 20 rejected examples; the human columns remain blank. quarantine_review.csv adds the six held examples. All 59,454 source reason records remain in reason_labels.jsonl; 3,130 passed v1 extraction before protocol filtering, six are now quarantined, and 3,094 Explain records remain after protocol filtering and holds. Original extraction-rejection categories remain unchanged. Counts label the original extraction stage separately from final quarantine eligibility.", "", "## Participant and task distribution", "", table(["Participant", "Partition", "Explain", "Track"], [[person, p, total(p, person, "explain"), total(p, person, "track")] for person in [f"P{i:02}" for i in range(1,10)] for p in PARTITIONS if person in manifest["partitions"][p]["participants"]]), "", "Explain test remains 11 P08 and 1,306 P09 records (99.16% P09). Keep participant-specific metrics; pooled Explain accuracy cannot represent balanced P08/P09 performance. Natural task mixture is proposed, without dataset duplication or silent oversampling. Report why performance separately from Track and other fields.", "", f"The identical WHY-only second-stage pool for extra-SFT and GRPO is {second['v2_count']} eligible IDs (147 in v1). See second_stage_explain_ids.json and swift/second_stage.explain.jsonl / .prompts.jsonl / .scoring.jsonl. The full second-stage pool also contains Track records; it is not interchangeable with this WHY-only set. Any future Track replay must be matched between methods.", "", "## Skips, labels and extraction rules", "", table(["Task", "Skip category", "Count"], [[task, category, total(task=task, kind="skipped", category=category)] for task in ("explain", "track") for category in sorted({x["category"] for x in dims if x["task"] == task and x["kind"] == "skipped"})]), "", table(["Goal status", "Count"], [[category, total(kind="goal", category=category)] for category in ("available", "missing_activity", "ambiguous_activity")]), "", table(["Final Explain rule", "Count"], [[rule, total(task="explain", kind="reason_rule", category=rule)] for rule in ("because", "in_order_to", "so_can", "so_that")]), "", "counts.csv / counts.json contain partition × participant × task × rule / goal / skip / quarantine counts. skipped_queries.jsonl preserves every original protocol skip. No overlap-of-words rejection is applied.", "", "## Alignment and cache verification", "", f"All {frames['records_verified']:,} records passed the cached actual-PTS, ordered-frame, causal history, strict-future, requested-tag, exact-span, cache-identity and file-hash checks. {frames['unique_frames_verified']:,} unique retained JPEGs total {frames['frame_cache_bytes']/1024**3:.3f} GiB. v1's full cache remains intact (382,065 JPEGs, 10.813 GiB); no new frame was decoded or extracted. Metadata/filesystem overhead is additional. annotation_alignment_audit.json independently reconciles source annotations; revision_audit.json rereads serialized model exports and aligned sidecars. These checks do not establish semantic label correctness.", "", "## Historical benchmark eligibility", "", "The benchmark overlap audit is unchanged: 19 historical reserved questions on validation videos and 179 on test videos remain eligible for fresh held-out evaluation. The other 202 historical reserved questions have source videos in a training partition. Old dev questions on held-out participant videos remain development-exposed. Exact membership is in benchmark_overlap.json and benchmark_overlap.csv; do not call all 400 old reserved questions held out.", "", "## Local environment and proposed settings", "", f"Local checkpoint: {env['checkpoint']['model']} at {env['checkpoint']['path']}; all {env['checkpoint']['shard_count']} weight shards are present. config.json / preprocessor_config.json and hashes are recorded in local_environment.json. No model weights were loaded.", "", "No ms-swift installation was found in the inspected environments. The preparation env has Torch 2.1.2+cu121 / Transformers 4.40.2; the accessible vLLM env has vLLM 0.23.0 / Torch 2.11.0 / Transformers 5.14.1. qic metadata has Transformers 5.17.0, PEFT 0.21.0 and Accelerate 1.15.0, but its Python executable is inaccessible to this user. These package versions do not establish a working SFT framework. No packages were installed.", "", table(["GPU", "Model", "Total MiB", "Used MiB", "Free MiB", "Utilization %"], [[g["index"], g["model"], g["total_mib"], g["used_mib"], g["free_mib"], g["utilization_percent"]] for g in gpu]), "", "The successful host snapshot is timestamped in gpu_inventory_verified.json; all eight devices were occupied. No device was reserved, freed or selected. Sandboxed nvidia-smi cannot access device nodes; the read-only host query supplied the inventory.", "", "proposed_training_config.json is a proposal, not a runnable training launch: two idle 48 GiB GPUs with ZeRO-3 base-weight sharding, BF16 text-decoder LoRA rank 16, per-device batch 1 × two data-parallel ranks × accumulation 8 = effective batch 16, context 8,192, gradient checkpointing, no packing, assistant-only loss. Each of 16 images uses min_pixels=65,536 / max_pixels=147,456; patch 16 and merge 2 imply at most 144 visual tokens per image (2,304 for 16, plus boundary/text tokens). Memory feasibility and actual trainer masking remain unverified.", ""]
    if preflight:
        lengths = [r["full_context_tokens"] for r in preflight["rows"]]
        lines.extend([f"CPU-only local HF processor preflight passed all 20 training rows: all 16 images survived and complete targets fit in {min(lengths)}–{max(lengths)} tokens, below 8,192. Actual grids and token counts are in processor_preflight.json. This loaded only the processor/tokenizer, not model weights, and is not an SFT smoke test or a validation of ms-swift's loss mask.", ""])
    lines.extend(["## Rerun and review package", "", "```bash", "cd /data/yaxuanli/ActGround", "bash scripts/prepare_hdepic_sft_v2.sh", "```", "", "The launcher validates immutable v1, builds v2 text, checks source alignment, audits cached images, writes all four ms-swift exports and scoring/prompt sidecars, runs the CPU processor preflight, reports environment/proposals, verifies preservation and packages source. It reuses v1 JPEG paths and cannot launch training. HDEPIC_V1_OUTPUT, HDEPIC_V2_OUTPUT, HDEPIC_PREP_PYTHON and HDEPIC_PROCESSOR_PYTHON override the corresponding paths.", "", "The ZIP includes code/hdepic_preparation, the requested four v1 script wrappers and the new v2 launcher, shared E0 helper dependencies, relevant tests, all four full text and model exports/sidecars, system prompt, 20 initial-SFT examples (five per task × goal-present/absent category), their 320 individual JPEGs and contact previews. Portable sample paths and their absolute-path mapping are included. Full exports reference the preserved local v1 cache, which is not embedded in the ZIP. Contact sheets are review aids only.", "", "Stop here for source/export and human reason-label review. The later short local SFT smoke test must check actual assistant-only loss, all 16 images, target truncation, finite loss/gradients, LoRA updates and checkpoint reload. Freeze the validation scoring/generation protocol and save base-model validation predictions before full training. No new test predictions should be inspected during development. No smoke test, base prediction or training has been performed in this task.", ""])
    atomic_write_text(out / "README.md", "\n".join(lines))
    code = sorted((PROJECT / "code/hdepic_preparation").glob("*.py")) + [PROJECT / "scripts" / name for name in ("build_hdepic_supervision.py", "extract_frames.py", "make_swift_sft.py", "prepare_hdepic_sft.sh", "prepare_hdepic_sft_v2.sh")]
    atomic_write_json(out / "build_provenance.json", {"version": policy["version"], "source_v1": str(source), "source_split_sha256": policy["source_split_sha256"], "dataset_fingerprint": text_fingerprint(out), "code_sha256": {str(p.relative_to(PROJECT)): sha256_file(p) for p in code}, "training_started": False, "model_inference_calls": 0, "frames_decoded": 0, "status": "pending_human_reason_label_review"})
    print(f"Serialized revision audit passed; report saved: {out / 'README.md'}", flush=True)


if __name__ == "__main__":
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    report(p.parse_args().output.resolve())
